        setMaxShadingQuality(value);
    value = std::min(maxShadingQuality, value);
    value = std::max(0.0f, value);
    if (value != minShadingQuality) {
        minShadingQuality = value;
        raisePropertyChanged(prop_minShadingQuality);
    }
}

